use xiom.io;

fn double_all(v: &mut Vec[Int]) {
  let i = 0;
  while i < v.len() {
    v[i] = v[i] * 2;
    i = i + 1;
  }
}

fn main() -> Int {
  var data = Vec[Int].new();
  data.push(1);
  data.push(2);
  data.push(3);
  double_all(&mut data);
  io.println(data[0].to_str());
  return data[0];
}
